from pathlib import Path
from datetime import datetime
import ast
import py_compile
import re

PATCH_NAME = "9_0_12d_contract_system_real_implementation"
START_MARKER = "# ✅ ROM 9.0.3 CONTRACT SYSTEM FACADE WRAPPERS V1"
END_MARKER = "# ✅ REFACTOR 9.0.4 ENERGY SYSTEM FACADE"
MODULE_TEMPLATE = '"""ROM Contract System - real implementation generated by patch 9.0.12d."""\nfrom datetime import date, datetime, timedelta\nimport random\nimport db as _db\n\n# Reuse shared infrastructure/API without delegating contract functions to legacy refs.\nfor _name, _value in list(vars(_db).items()):\n    if _name not in globals() and not _name.startswith("__"):\n        globals()[_name] = _value\n\ntry:\n    from data.balance import CONTRACTS_UNLOCK_LEVEL, CONTRACT_MOBS_EQUIVALENT, CONTRACT_TARGET_KILLS, DAILY_CONTRACT_LIMIT\nexcept Exception:\n    CONTRACTS_UNLOCK_LEVEL = int(getattr(_db, "CONTRACTS_UNLOCK_LEVEL", 5) or 5)\n    CONTRACT_MOBS_EQUIVALENT = int(getattr(_db, "CONTRACT_MOBS_EQUIVALENT", 20) or 20)\n    CONTRACT_TARGET_KILLS = int(getattr(_db, "CONTRACT_TARGET_KILLS", 5) or 5)\n    DAILY_CONTRACT_LIMIT = int(getattr(_db, "DAILY_CONTRACT_LIMIT", 5) or 5)\n\nDEFAULT_CONTRACT_TARGET_KILLS = 5\n\ndef get_contract_target_kills():\n    return int(CONTRACT_TARGET_KILLS or DEFAULT_CONTRACT_TARGET_KILLS)\n\ndef get_contract_mobs_equivalent(*args, **kwargs):\n    return int(CONTRACT_MOBS_EQUIVALENT or 20)\n\n__EXTRACTED__\n\n__BASE_CLAIM__\n\ndef _contract_result_success(result):\n    if not isinstance(result, dict):\n        return False\n    if result.get("success") is True:\n        return True\n    return "контракт здано" in str(result.get("message") or "").lower()\n\ndef claim_contract_reward(user_id):\n    contract = get_active_contract(user_id)\n    result = _claim_contract_reward_base(user_id)\n    if not _contract_result_success(result):\n        return result\n    try:\n        guild_result = _db.award_guild_contract_completion(user_id=user_id, contract=contract or "контракт")\n        guild_text = _db.get_guild_activity_reward_text(guild_result)\n        if guild_text and isinstance(result, dict):\n            message = str(result.get("message") or "")\n            if guild_text not in message:\n                result["message"] = (message.rstrip() + "\\n\\n" + guild_text).strip()\n    except Exception as error:\n        print(f"WARNING: Guild contract reward failed: {error}")\n    return result\n\ndef get_daily_contract_reset_info(user_id=None):\n    today = get_today_str()\n    if user_id is None:\n        return {"today": today}\n    row = cursor.execute("SELECT daily_contract_date, daily_contracts_completed FROM users WHERE user_id=?", (user_id,)).fetchone()\n    if not row:\n        return {"today": today, "date": "", "completed": 0}\n    return {"today": today, "date": row[0] or "", "completed": int(row[1] or 0)}\n\ndef migrate_contract_target_kills_to_v2(*args, **kwargs):\n    return migrate_active_contracts_target_kills_to_5()\n'
FACADE_BLOCK = '# ✅ ROM 9.0.3 CONTRACT SYSTEM FACADE WRAPPERS V2 - REAL IMPLEMENTATION\n\ndef _contract_system_v2():\n    from systems import contract_system as _mod\n    return _mod\n\ndef get_today_str(*args, **kwargs): return _contract_system_v2().get_today_str(*args, **kwargs)\ndef init_contract_system(*args, **kwargs): return _contract_system_v2().init_contract_system(*args, **kwargs)\ndef reset_daily_contracts_if_needed(*args, **kwargs): return _contract_system_v2().reset_daily_contracts_if_needed(*args, **kwargs)\ndef reset_daily_hunts_if_needed(*args, **kwargs): return _contract_system_v2().reset_daily_hunts_if_needed(*args, **kwargs)\ndef get_active_contract(*args, **kwargs): return _contract_system_v2().get_active_contract(*args, **kwargs)\ndef get_contract_status(*args, **kwargs): return _contract_system_v2().get_contract_status(*args, **kwargs)\ndef create_daily_contract(*args, **kwargs): return _contract_system_v2().create_daily_contract(*args, **kwargs)\ndef abandon_active_contract(*args, **kwargs): return _contract_system_v2().abandon_active_contract(*args, **kwargs)\ndef process_contract_progress_on_kill(*args, **kwargs): return _contract_system_v2().process_contract_progress_on_kill(*args, **kwargs)\ndef claim_contract_reward(*args, **kwargs): return _contract_system_v2().claim_contract_reward(*args, **kwargs)\ndef get_daily_contract_reset_info(*args, **kwargs): return _contract_system_v2().get_daily_contract_reset_info(*args, **kwargs)\ndef get_contract_mobs_equivalent(*args, **kwargs): return _contract_system_v2().get_contract_mobs_equivalent(*args, **kwargs)\ndef migrate_contract_target_kills_to_v2(*args, **kwargs): return _contract_system_v2().migrate_contract_target_kills_to_v2(*args, **kwargs)\ntry:\n    CONTRACT_TARGET_KILLS = _contract_system_v2().get_contract_target_kills()\n    CONTRACT_MOBS_EQUIVALENT = _contract_system_v2().get_contract_mobs_equivalent()\nexcept Exception:\n    pass\n\n'
SMOKE_TEST = 'from pathlib import Path\nimport sys\nROOT = Path(__file__).resolve().parents[1]\nif str(ROOT) not in sys.path: sys.path.insert(0, str(ROOT))\nimport db\nUID = 243129101\nstatus = db.get_contract_status(UID)\nactive = db.get_active_contract(UID)\nassert isinstance(status, dict), type(status)\nassert active is None or isinstance(active, dict), type(active)\nassert int(getattr(db, "CONTRACT_TARGET_KILLS", 0)) == 5\nfor name in ("create_daily_contract", "abandon_active_contract", "process_contract_progress_on_kill", "claim_contract_reward"):\n    assert callable(getattr(db, name, None)), name\nprint("[OK] contract runtime contracts")\nprint("- target_kills:", db.CONTRACT_TARGET_KILLS)\nprint("- status keys:", sorted(status.keys()))\nprint("- active:", active)\n'
DIRECT_FUNCTIONS = ["get_today_str", "init_contract_system", "reset_daily_contracts_if_needed", "reset_daily_hunts_if_needed", "get_active_contract", "get_contract_status", "create_daily_contract", "abandon_active_contract", "process_contract_progress_on_kill", "migrate_active_contracts_target_kills_to_5"]

def backup(root, path):
    d = root / "backup"; d.mkdir(exist_ok=True)
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    safe = str(path.relative_to(root)).replace("\\", "_").replace("/", "_")
    out = d / f"{safe}_{PATCH_NAME}_{stamp}.bak"
    out.write_text(path.read_text(encoding="utf-8"), encoding="utf-8")
    return out

def source_of(text, node):
    lines = text.splitlines(keepends=True)
    return "".join(lines[node.lineno-1:node.end_lineno]).rstrip() + "\n"

def definitions_before(text, offset):
    tree = ast.parse(text); lines = text.splitlines(keepends=True); starts=[]; total=0
    for line in lines: starts.append(total); total += len(line)
    found = {}
    for node in tree.body:
        if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)) and starts[node.lineno-1] < offset:
            found.setdefault(node.name, []).append(node)
    return found

def build_system(db_text):
    cut = db_text.find(START_MARKER)
    if cut < 0: raise RuntimeError("contract facade marker not found")
    defs = definitions_before(db_text, cut)
    missing = [n for n in DIRECT_FUNCTIONS if n not in defs]
    if missing: raise RuntimeError(f"missing contract definitions: {missing}")
    extracted = "\n".join(source_of(db_text, defs[n][-1]) for n in DIRECT_FUNCTIONS)
    claims = defs.get("claim_contract_reward", [])
    if not claims: raise RuntimeError("claim_contract_reward not found")
    base_node = claims[-2] if len(claims) >= 2 else claims[-1]
    base = source_of(db_text, base_node)
    base = re.sub(r"(?m)^def\s+claim_contract_reward\s*\(", "def _claim_contract_reward_base(", base, count=1)
    return MODULE_TEMPLATE.replace("__EXTRACTED__", extracted).replace("__BASE_CLAIM__", base)

def patch_db(text):
    a=text.find(START_MARKER); b=text.find(END_MARKER)
    if a < 0 or b < 0 or b <= a: raise RuntimeError("cannot locate facade boundaries")
    return text[:a] + FACADE_BLOCK + text[b:]

def main():
    root=Path(__file__).resolve().parents[1]
    dbp=root/"db.py"; sysp=root/"systems"/"contract_system.py"; testp=root/"tools"/"smoke_test_contract_contracts.py"
    if not dbp.exists() or not sysp.exists(): raise SystemExit("db.py or contract_system.py missing")
    old_db=dbp.read_text(encoding="utf-8"); old_sys=sysp.read_text(encoding="utf-8")
    backups=[backup(root, dbp), backup(root, sysp)]
    try:
        sysp.write_text(build_system(old_db), encoding="utf-8")
        dbp.write_text(patch_db(old_db), encoding="utf-8")
        testp.write_text(SMOKE_TEST, encoding="utf-8")
        for p in (sysp, dbp, testp): py_compile.compile(str(p), doraise=True)
    except Exception as e:
        dbp.write_text(old_db, encoding="utf-8"); sysp.write_text(old_sys, encoding="utf-8")
        raise SystemExit(f"Patch failed; restored files.\n{e}")
    print("✅ Patch 9.0.12d applied successfully.")
    print("✅ Contract SQL logic now lives in systems/contract_system.py.")
    print("✅ Legacy contract capture facade replaced by direct wrappers.")
    print("Backup:")
    for p in backups: print("-", p)
    print("Checks:")
    print(r"python -m py_compile .\systems\contract_system.py")
    print(r"python -m py_compile .\db.py")
    print("python tools/check_imports.py")
    print("python tools/smoke_test_rom_core.py")
    print("python tools/smoke_test_contract_contracts.py")
    print("python tools/db_cleanup_readiness.py")

if __name__ == "__main__": main()
